// Normalize inputs for the enrich-content webhook.
const input = $input.first().json;
const form = (input && typeof input.body === 'object' && input.body !== null && Object.keys(input.body).length > 0)
  ? input.body
  : input;

const norm = s => String(s).toLowerCase().replace(/[^a-z0-9]/g, '');
const pick = (...keys) => {
  for (const k of keys) {
    if (form[k] !== undefined && form[k] !== null && form[k] !== '') return form[k];
  }
  const targets = keys.map(norm);
  for (const k of Object.keys(form)) {
    const n = norm(k);
    if (targets.some(t => n === t || n.startsWith(t))) return form[k];
  }
  return '';
};

const content = String(pick('content', 'markdown', 'final_content', 'edited_content') || '').trim();
const focusKeyword = String(pick('focus_keyword', 'Focus Keyword', 'focusKeyword') || '').trim();

let internalLinks = form.internal_links;
if (typeof internalLinks === 'string') {
  internalLinks = internalLinks.split(/[\n,;]/).map(s => s.trim()).filter(Boolean);
}
if (Array.isArray(internalLinks)) {
  internalLinks = internalLinks.filter(u => typeof u === 'string' && /^https?:\/\//.test(u));
} else {
  internalLinks = [];
}

const mediaLibraryId = parseInt(pick('media_library_id', 'mediaLibraryId', 'ml_id')) || 0;

if (!content) {
  return [{ json: { error: 'content is required (non-empty markdown)' } }];
}

return [{
  json: {
    content,
    focus_keyword: focusKeyword,
    internal_links: internalLinks,
    media_library_id: mediaLibraryId,
    original_word_count: content.split(/\s+/).filter(Boolean).length
  }
}];

// Fetch media library items if media_library_id is provided.
// Passes through all form data from Normalize, adds media_items array.

const form = $('Normalize Inputs').first().json;

if (form.error) {
  return [{ json: form }];
}

const mlId = form.media_library_id || 0;

if (!mlId) {
  return [{ json: { ...form, media_items: [] } }];
}

try {
  const ML_WEBHOOK = 'https://n8n.srv1195841.hstgr.cloud/webhook/ml-manager';
  const resp = await this.helpers.httpRequest({
    method: 'POST',
    url: ML_WEBHOOK,
    headers: { 'Content-Type': 'application/json' },
    body: { action: 'list_items', collection_id: mlId },
    json: true,
    timeout: 15000
  });

  // n8n 'All Incoming Items' wraps response in array
  const data = Array.isArray(resp) ? resp[0] : resp;
  const items = data.items || [];
  return [{ json: { ...form, media_items: items } }];
} catch (e) {
  return [{ json: { ...form, media_items: [], media_error: e.message } }];
}

// Build the OpenRouter request body for the enrichment pass.
//
// Reused OPENROUTER_API_KEY. ENRICH_MODEL is swappable here.

const OPENROUTER_API_KEY = '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';
const ENRICH_MODEL      = 'anthropic/claude-sonnet-4.5';

const form = $('Fetch Media Items').first().json;

if (form.error) {
  return [{ json: form }];
}

if (!form.content) {
  return [{ json: { error: 'content is required' } }];
}

const systemPrompt =
  'You are a precise content enrichment engine. Your job: take a finished markdown document and insert internal links, images, and YouTube videos at contextually relevant spots WITHOUT altering the original prose.\n\n' +
  'ABSOLUTE RULES (NON-NEGOTIABLE):\n' +
  '1. PRESERVE PROSE WORD-FOR-WORD. Do not rewrite, paraphrase, reorder, add, restructure, or remove sentences. The ONLY allowed change is wrapping EXISTING words in markdown link syntax [existing words](URL) where an internal link is inserted, plus inserting image lines or YouTube standalone lines at section boundaries. Do not change punctuation, headings, or whitespace.\n' +
  '2. NEVER insert internal links inside the H1 line, inside the first paragraph (intro), or inside the conclusion section.\n' +
  '3. INTERNAL LINKS: Only link when the surrounding paragraph topic genuinely matches the URL path topic (derive the topic from the URL slug). Anchor text MUST be existing words drawn from the sentence being linked. Format: [existing words from the sentence](URL). Max 1 link per paragraph. Max 1 link per URL (do not reuse a URL). No more than 5 internal links total. Skip a URL if no paragraph is a real topical match -- never force.\n' +
  '4. IMAGES: Use markdown ![alt_text](url) on its own line, placed directly below the LAST paragraph of an H2 section where the image directly supports the content. Max 1 image per H2 section. Skip if no fit. Use the exact alt_text provided in the media library block.\n' +
  '5. YOUTUBE: Place as a standalone line directly below the H2 paragraph where the video is topically relevant. Format: [Watch: short descriptive label](URL). Max 1 YouTube link per blog post. Skip if no fit.\n' +
  '6. DO NOT add new headings, subheadings, bullet lists, or section breaks. DO NOT change heading text.\n' +
  '7. DO NOT add commentary, preambles, explanations, or summary text.\n' +
  '8. OUTPUT: Pure markdown only. The full enriched document (entire content, with insertions). No code fences, no wrapping, no extra text.\n' +
  '9. If no internal_links fit, no images fit, and no YouTube fits anywhere -- return the original markdown EXACTLY as received.\n' +
  '10. If <internal_links> is empty, skip internal linking entirely. If <media_library> is empty or missing, skip all media insertion.\n' +
  '11. PRESERVE the original H1 line exactly. PRESERVE list items exactly (you may insert a link inside a list item if rule 3 otherwise allows).\n' +
  '12. WORD COUNT TOLERANCE: Your output word count MUST be within +3% of the original (insertions add very few words). If you find yourself adding substantive prose, STOP -- you are breaking rule 1.';

const parts = [];
parts.push('<original_content>');
parts.push(form.content);
parts.push('</original_content>');
parts.push('');

if (form.focus_keyword) {
  parts.push('<focus_keyword>' + form.focus_keyword + '</focus_keyword>');
  parts.push('');
}

const internalLinks = form.internal_links || [];
if (internalLinks.length > 0) {
  parts.push('<internal_links>');
  parts.push('Available internal URLs for contextual linking. Link ONLY where the surrounding paragraph topic genuinely matches the URL slug. Use existing words in the sentence as anchor text. Max 5 links total. Max 1 link per URL. Never force a fit.');
  parts.push(internalLinks.map(u => '- ' + u).join('\n'));
  parts.push('</internal_links>');
  parts.push('');
} else {
  parts.push('<internal_links>');
  parts.push('(none -- skip internal linking)');
  parts.push('</internal_links>');
  parts.push('');
}

const mediaItems = form.media_items || [];
const images = mediaItems.filter(i => i.media_type === 'image');
const videos = mediaItems.filter(i => i.media_type === 'youtube');

if (images.length > 0 || videos.length > 0) {
  parts.push('<media_library>');
  parts.push('Available media for this content. Only insert where the surrounding section topic genuinely matches the media topic (derive from alt_text or filename).');
  if (images.length > 0) {
    parts.push('');
    parts.push('IMAGES (insert as ![alt_text](url) on its own line at the END of the relevant H2 section, max 1 per H2):');
    images.forEach(img => {
      parts.push('- alt_text: "' + (img.alt_text || 'image').replace(/"/g, '\\"') + '" | url: ' + img.url);
    });
  }
  if (videos.length > 0) {
    parts.push('');
    parts.push('YOUTUBE (insert as a standalone line directly below the relevant H2 paragraph, format: [Watch: short label](url). Max 1 per post):');
    videos.forEach(v => {
      parts.push('- url: ' + v.url + ' | label: ' + (v.alt_text || 'Watch video').replace(/[\[\]]/g, ''));
    });
  }
  parts.push('</media_library>');
  parts.push('');
} else {
  parts.push('<media_library>');
  parts.push('(none -- skip media insertion)');
  parts.push('</media_library>');
  parts.push('');
}

parts.push('Enrich the <original_content> with internal links, images, and YouTube embeds following the ABSOLUTE RULES. Return only the full enriched markdown.');

const userPrompt = parts.join('\n');

return [{
  json: {
    form,
    enrich_model: ENRICH_MODEL,
    openrouter_api_key: OPENROUTER_API_KEY,
    openrouter_request: {
      model: ENRICH_MODEL,
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user',   content: userPrompt }
      ],
      temperature: 0.2,
      max_tokens: 16384
    }
  }
}];

// Extract enriched markdown from OpenRouter response. Compute diff stats.
const resp = $input.first().json;
const payload = $('Build Enrich Prompt').first().json;

if (payload.error) {
  return [{ json: payload }];
}

if (resp.error) {
  return [{ json: { error: 'OpenRouter returned error', detail: resp.error } }];
}

const content = resp?.choices?.[0]?.message?.content;
if (!content) {
  return [{ json: { error: 'No content in OpenRouter response', raw: resp } }];
}

// Strip code fences if the LLM wrapped output in ```markdown ... ```.
const enriched = content
  .replace(/^```(?:markdown|md)?\s*/i, '')
  .replace(/\s*```\s*$/i, '')
  .trim();

const original = payload.form?.content || '';
const originalWordCount = payload.form?.original_word_count || original.split(/\s+/).filter(Boolean).length;
const enrichedWordCount = enriched.split(/\s+/).filter(Boolean).length;

// Count existing markdown link occurrences in original vs enriched.
const mdLinkRe = /\]\((https?:\/\/[^\s)]+)\)/g;
const imgRe = /!\[[^\]]*\]\([^)]*\)/g;
const ytRe = /(?:youtube\.com\/watch|youtu\.be\/)[^\s)\]]+/gi;

function collectUrls(text, re) {
  const set = new Set();
  let m;
  while ((m = re.exec(text)) !== null) {
    set.add(m[1]);
  }
  return set;
}

const originalLinkUrls = collectUrls(original, mdLinkRe);

// Re-scan enriched with fresh regexes (exec stateful on global).
const enrichedLinkUrlsIter = (function* () {
  const re = /\]\((https?:\/\/[^\s)]+)\)/g;
  let m;
  while ((m = re.exec(enriched)) !== null) yield m[1];
})();

const providedInternalLinks = (payload.form?.internal_links || []).map(u => String(u).trim());
let internalLinksInserted = 0;
for (const u of enrichedLinkUrlsIter) {
  if (providedInternalLinks.includes(u) && !originalLinkUrls.has(u)) {
    internalLinksInserted += 1;
  }
}

const originalImgCount = (original.match(imgRe) || []).length;
const enrichedImgCount = (enriched.match(imgRe) || []).length;
const imagesInserted = Math.max(0, enrichedImgCount - originalImgCount);

const originalYtCount = (original.match(ytRe) || []).length;
const enrichedYtCount = (enriched.match(ytRe) || []).length;
const youtubeInserted = Math.max(0, enrichedYtCount - originalYtCount);

// Word count delta check. If delta exceeds 5%, flag a warning (LLM may have rewritten prose).
const delta = Math.abs(enrichedWordCount - originalWordCount);
const deltaPct = originalWordCount > 0 ? (delta / originalWordCount) * 100 : 0;
let warning = null;
if (deltaPct > 15) {
  warning = 'prose_changed: enriched word count deviates ' + deltaPct.toFixed(1) + '% from original (insertions should add <15%). Manual review recommended.';
}

return [{
  json: {
    content: enriched,
    stats: {
      internal_links_inserted: internalLinksInserted,
      images_inserted: imagesInserted,
      youtube_links_inserted: youtubeInserted,
      original_word_count: originalWordCount,
      enriched_word_count: enrichedWordCount,
      warning
    },
    usage: resp.usage || null,
    generated_at: new Date().toISOString()
  }
}];
